config.message:
// value is JSON such as {"temp": 21.5, "room": "lab"}
if (!jsonHas(value, "temp")) return;      // not a reading: ignore it
double c = jsonNumber(value, "temp");
send(Json()
  .add("room", jsonText(value, "room"))
  .add("celsius", c)
  .add("fahrenheit", c * 9 / 5 + 32, 1)  // 1 decimal place
  .add("hot", c > 30));
